CREATE FUNCTION os_field_fault_guard() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
 IF NEW.org_id<>TG_ARGV[0] THEN RETURN NEW; END IF;
 IF TG_TABLE_NAME='os_records' THEN IF NEW.id<>TG_ARGV[1] THEN RETURN NEW; END IF;
 ELSIF TG_TABLE_NAME='os_reports' THEN IF NEW.checksum<>TG_ARGV[1] THEN RETURN NEW; END IF;
 ELSIF TG_TABLE_NAME='os_events' THEN IF NEW.action<>TG_ARGV[1] THEN RETURN NEW; END IF;
 ELSE RAISE EXCEPTION USING ERRCODE='ZFD99',MESSAGE='fictional fixed fixture'; END IF;
 PERFORM nextval('os_field_fault_seq');
 RAISE EXCEPTION USING ERRCODE='ZFD01',MESSAGE='fictional fixed fixture';
END; $$;
